adjustment.mjs.text:
// Offline header allowance / charge (BT-92 / BT-99) observations.
// Mirrors src/einvoice_preflight/adjustment.py. Findings never repeat
// the amount, percent, or reason. Line-level AllowanceCharge is ignored.

import { looksLikePlaceholder } from "./reference.mjs";

const MAX_REASON = 100;

function roundHalfUpToCents(value) {
  if (!Number.isFinite(value)) return null;
  const sign = value < 0 ? -1 : 1;
  return (sign * Math.round(Math.abs(value) * 100 + Number.EPSILON)) / 100;
}

function parseNumber(value) {
  if (value === undefined || value === null || value === "") return null;
  const text = typeof value === "string" ? value.trim() : String(value);
  if (text === "" || !Number.isFinite(Number(text))) return null;
  const result = Number(text);
  return Number.isFinite(result) ? result : null;
}

function money(value) {
  const parsed = parseNumber(value);
  return parsed === null ? null : roundHalfUpToCents(parsed);
}

export function normalizeKind(value) {
  if (typeof value === "boolean") return value ? "charge" : "allowance";
  if (typeof value !== "string") return null;
  const compact = value.trim().toLowerCase();
  if (["true", "1", "charge", "surcharge"].includes(compact)) return "charge";
  if (["false", "0", "allowance", "discount"].includes(compact)) return "allowance";
  return null;
}

export function headerAdjustmentNetDelta(invoice) {
  let delta = 0;
  for (const row of rows(invoice)) {
    if (!row || typeof row !== "object" || Array.isArray(row)) continue;
    const kind = normalizeKind(row.kind);
    const amount = money(row.amount);
    if (kind === null || amount === null || amount < 0) continue;
    delta = roundHalfUpToCents(delta + (kind === "charge" ? amount : -amount));
  }
  return delta;
}

export function inspectHeaderAdjustments(invoice) {
  if (!invoice || typeof invoice !== "object" || Array.isArray(invoice) || !("adjustments" in invoice)) {
    return [];
  }
  const raw = invoice.adjustments;
  if (raw === null || raw === "") {
    return [finding(
      "INV-050",
      "Header allowance or charge list is empty or not a list of rows.",
      "Add adjustments as a list of allowance or charge rows, or omit adjustments.",
      "/adjustments",
    )];
  }
  if (!Array.isArray(raw)) {
    return [finding(
      "INV-050",
      "Header allowance or charge list is empty or not a list of rows.",
      "Add adjustments as a list of allowance or charge rows, or omit adjustments.",
      "/adjustments",
    )];
  }
  const findings = [];
  raw.forEach((row, index) => findings.push(...inspectRow(row, index)));
  return findings;
}

function rows(invoice) {
  return invoice && Array.isArray(invoice.adjustments) ? invoice.adjustments : [];
}

function inspectRow(row, index) {
  const path = `/adjustments/${index}`;
  if (!row || typeof row !== "object" || Array.isArray(row)) {
    return [finding(
      "INV-050",
      "Header allowance or charge row is not an object.",
      "Provide kind, amount, and a reason, or omit the row.",
      path,
    )];
  }
  const findings = [];
  const kind = "kind" in row ? normalizeKind(row.kind) : null;
  if (!("kind" in row) || kind === null) {
    findings.push(finding(
      "INV-050",
      "Header allowance or charge kind is missing or not allowance or charge.",
      "Set kind to allowance or charge, or omit the row.",
      `${path}/kind`,
    ));
  }

  let amount = null;
  if (!("amount" in row) || row.amount === null || row.amount === "") {
    findings.push(finding(
      "INV-050",
      "Header allowance or charge amount is missing or invalid.",
      "Provide a non-negative amount, or omit the row.",
      `${path}/amount`,
    ));
  } else {
    amount = money(row.amount);
    if (amount === null || amount < 0) {
      findings.push(finding(
        "INV-050",
        "Header allowance or charge amount is missing or invalid.",
        "Provide a non-negative amount, or omit the row.",
        `${path}/amount`,
      ));
      amount = null;
    }
  }

  let base = null;
  let percent = null;
  if ("base" in row && row.base !== null && row.base !== "") {
    base = money(row.base);
    if (base === null || base < 0) {
      findings.push(finding(
        "INV-051",
        "Header allowance or charge base is missing or invalid.",
        "Provide a non-negative base amount, or omit base and percent.",
        `${path}/base`,
      ));
      base = null;
    }
  }
  if ("percent" in row && row.percent !== null && row.percent !== "") {
    percent = parseNumber(row.percent);
    if (percent === null || percent < 0 || percent > 100) {
      findings.push(finding(
        "INV-051",
        "Header allowance or charge percentage is missing or invalid.",
        "Use a percentage between 0 and 100, or omit percent and base.",
        `${path}/percent`,
      ));
      percent = null;
    }
  }
  if (amount !== null && base !== null && percent !== null) {
    const expected = roundHalfUpToCents((base * percent) / 100);
    if (amount !== expected) {
      findings.push(finding(
        "INV-051",
        "Header allowance or charge amount does not match its percentage of the base.",
        `Set the amount to ${expected.toFixed(2)} or correct percent and base.`,
        `${path}/amount`,
      ));
    }
  }

  if ("reason" in row || "reason_code" in row) {
    const reason = row.reason;
    const code = row.reason_code;
    const hasReason = typeof reason === "string" && reason.trim() && !looksLikePlaceholder(reason);
    const hasCode = typeof code === "string" && code.trim() && !looksLikePlaceholder(code);
    if (typeof reason === "string" && reason.trim().length > MAX_REASON) {
      findings.push(finding(
        "INV-052",
        "Header allowance or charge reason is longer than the usual 100-character network field.",
        "Shorten the reason so a receiving system can store it, or omit the row.",
        `${path}/reason`,
      ));
    } else if (!hasReason && !hasCode) {
      findings.push(finding(
        "INV-052",
        "Header allowance or charge reason is empty or a placeholder.",
        "Add a settlement or packing reason, or omit reason and reason_code.",
        "reason" in row ? `${path}/reason` : `${path}/reason_code`,
      ));
    }
  } else {
    findings.push(finding(
      "INV-052",
      "Header allowance or charge has no reason.",
      "Add a reason such as a settlement or packing description, or omit the row.",
      `${path}/reason`,
    ));
  }
  return findings;
}

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

bic.mjs.text:
// Offline BIC shape and IBAN-country observations.
// Typo catch only — not a SWIFT lookup and not a claim funds can be received.

import { looksLikeCompleteIban, normalizeIban } from "./iban.mjs";

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function normalizeBic(value) {
  if (typeof value !== "string") return null;
  const compact = value.toUpperCase().replace(/[^A-Z0-9]/g, "");
  return compact || null;
}

function classify(compact) {
  if (compact.length !== 8 && compact.length !== 11) return "unknown";
  const bank = compact.slice(0, 4);
  const country = compact.slice(4, 6);
  const location = compact.slice(6, 8);
  const branch = compact.slice(8);
  if (!/^[A-Z]{4}$/.test(bank) || !/^[A-Z]{2}$/.test(country)) return "unknown";
  if (!/^[A-Z0-9]{2}$/.test(location)) return "unknown";
  if (branch && !/^[A-Z0-9]{3}$/.test(branch)) return "unknown";
  return "ok";
}

export function looksLikeCompleteBic(value) {
  const compact = normalizeBic(value);
  return compact !== null && classify(compact) === "ok";
}

function checkExplicit(value, path) {
  if (typeof value !== "string" || !value.trim()) {
    return [finding(
      "INV-026",
      "Payment BIC is empty or not text.",
      "Provide the BIC as text, or omit payment.bic.",
      path,
    )];
  }
  const compact = normalizeBic(value);
  if (compact === null) {
    return [finding(
      "INV-026",
      "Payment BIC is empty or not text.",
      "Provide the BIC as text, or omit payment.bic.",
      path,
    )];
  }
  if (classify(compact) === "unknown") {
    return [finding(
      "INV-026",
      "Payment BIC is not an 8- or 11-character bank identifier.",
      "Use four letters, a two-letter country, a two-character location, and an optional three-character branch, or omit payment.bic.",
      path,
    )];
  }
  return [];
}

function countryMismatch(payment) {
  const compactBic = normalizeBic(payment.bic);
  const compactIban = normalizeIban(payment.iban);
  if (compactBic === null || compactIban === null) return [];
  if (!looksLikeCompleteBic(compactBic) || !looksLikeCompleteIban(compactIban)) return [];
  const bicCountry = compactBic.slice(4, 6);
  const ibanCountry = compactIban.slice(0, 2);
  if (bicCountry === ibanCountry) return [];
  return [finding(
    "INV-027",
    "Payment BIC country does not match the payment IBAN country.",
    "Correct the BIC or the IBAN so both use the same country, or omit payment.bic.",
    "/payment/bic",
  )];
}

export function inspectPaymentBic(invoice) {
  const payment = invoice.payment;
  if (!payment || typeof payment !== "object" || Array.isArray(payment)) return [];
  const bic = payment.bic;
  if (bic === undefined || bic === null || bic === "") return [];
  const findings = checkExplicit(bic, "/payment/bic");
  if (findings.length) return findings;
  return countryMismatch(payment);
}

breakdown.mjs.text:
// Offline mixed-rate tax-breakdown observations.
// Arithmetic / document-shape only — not a tax-law determination.

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

function parseNumber(value) {
  if (value === undefined || value === null || value === "") return null;
  const text = typeof value === "string" ? value.trim() : String(value);
  if (text === "" || !Number.isFinite(Number(text))) return null;
  const result = Number(text);
  return Number.isFinite(result) ? result : null;
}

function roundHalfUpToCents(value) {
  if (!Number.isFinite(value)) return null;
  const sign = value < 0 ? -1 : 1;
  return (sign * Math.round(Math.abs(value) * 100 + Number.EPSILON)) / 100;
}

function money(value) {
  const parsed = parseNumber(value);
  return parsed === null ? null : roundHalfUpToCents(parsed);
}

function rateKey(value) {
  const parsed = parseNumber(value);
  return parsed === null ? null : String(parsed);
}

function lineGroups(lines) {
  const groups = new Map();
  if (!Array.isArray(lines)) return groups;
  for (const line of lines) {
    if (!line || typeof line !== "object" || Array.isArray(line)) continue;
    const quantity = parseNumber(line.quantity);
    const price = money(line.unit_price);
    const tax = parseNumber(line.tax_percent);
    if (quantity === null || quantity <= 0 || price === null || price < 0) continue;
    if (tax === null || tax < 0 || tax > 100) continue;
    const lineNet = roundHalfUpToCents(quantity * price);
    const lineTax = roundHalfUpToCents(lineNet * tax / 100);
    const key = rateKey(tax);
    const bucket = groups.get(key) || { taxable: 0, tax: 0 };
    bucket.taxable = roundHalfUpToCents(bucket.taxable + lineNet);
    bucket.tax = roundHalfUpToCents(bucket.tax + lineTax);
    groups.set(key, bucket);
  }
  return groups;
}

function checkRows(rows, expected) {
  const findings = [];
  const seen = new Map();
  rows.forEach((row, index) => {
    const path = `/tax_breakdown/${index}`;
    if (!row || typeof row !== "object" || Array.isArray(row)) {
      findings.push(finding(
        "INV-038",
        `Tax breakdown row ${index + 1} is not an object.`,
        "Provide tax_percent, taxable, and tax on each breakdown row.",
        path,
      ));
      return;
    }
    const percent = parseNumber(row.tax_percent);
    const taxable = money(row.taxable);
    const tax = money(row.tax);
    if (percent === null || percent < 0 || percent > 100) {
      findings.push(finding(
        "INV-038",
        `Tax breakdown row ${index + 1} tax percentage is missing or invalid.`,
        "Use the tax percentage supplied by your authoritative source; this tool does not choose it.",
        `${path}/tax_percent`,
      ));
      return;
    }
    const key = rateKey(percent);
    if (seen.has(key)) {
      findings.push(finding(
        "INV-038",
        "Tax breakdown repeats the same tax percentage on more than one row.",
        "Keep one breakdown row per tax percentage.",
        `${path}/tax_percent`,
      ));
      return;
    }
    seen.set(key, index);
    if (taxable === null || taxable < 0) {
      findings.push(finding(
        "INV-038",
        `Tax breakdown row ${index + 1} taxable amount is missing or invalid.`,
        "Set taxable to the net of the lines at this rate.",
        `${path}/taxable`,
      ));
      return;
    }
    if (tax === null || tax < 0) {
      findings.push(finding(
        "INV-038",
        `Tax breakdown row ${index + 1} tax amount is missing or invalid.`,
        "Set tax to taxable times the row percentage, rounded to cents.",
        `${path}/tax`,
      ));
      return;
    }
    const expectedTax = roundHalfUpToCents(taxable * percent / 100);
    if (tax !== expectedTax) {
      findings.push(finding(
        "INV-038",
        `Tax breakdown row ${index + 1} tax amount does not equal taxable times the percentage.`,
        `Set tax to ${expectedTax} or correct taxable and tax_percent.`,
        `${path}/tax`,
      ));
    }
    const group = expected.get(key);
    if (!group) {
      findings.push(finding(
        "INV-038",
        `Tax breakdown row ${index + 1} names a tax percentage that no line uses.`,
        "Remove the extra row, or correct the line tax percentages.",
        `${path}/tax_percent`,
      ));
      return;
    }
    if (taxable !== group.taxable) {
      findings.push(finding(
        "INV-038",
        `Tax breakdown row ${index + 1} taxable amount does not match the lines at that rate.`,
        `Set taxable to ${group.taxable} or correct the line nets.`,
        `${path}/taxable`,
      ));
    }
  });
  for (const key of expected.keys()) {
    if (!seen.has(key)) {
      findings.push(finding(
        "INV-038",
        "Tax breakdown is missing a row for a tax percentage used on the lines.",
        "Add one breakdown row per line tax percentage.",
        "/tax_breakdown",
      ));
    }
  }
  return findings;
}

export function inspectTaxBreakdown(invoice) {
  if (!invoice || typeof invoice !== "object" || Array.isArray(invoice)) return [];
  const expected = lineGroups(invoice.lines);
  const supplied = invoice.tax_breakdown;
  const missing = !("tax_breakdown" in invoice) || supplied === null || supplied === undefined || supplied === "";
  if (missing || (Array.isArray(supplied) && supplied.length === 0)) {
    if (expected.size > 1) {
      return [finding(
        "INV-037",
        "Invoice mixes tax rates without a per-rate tax breakdown.",
        "Add tax_breakdown with one row per rate (tax_percent, taxable, tax), or use a single tax percentage.",
        "/tax_breakdown",
      )];
    }
    return [];
  }
  if (!Array.isArray(supplied)) {
    return [finding(
      "INV-038",
      "Tax breakdown is not a list of per-rate rows.",
      "Provide tax_breakdown as an array of objects with tax_percent, taxable, and tax.",
      "/tax_breakdown",
    )];
  }
  return checkRows(supplied, expected);
}

checks.mjs.text:
// Format-neutral invoice checks. Mirrors src/einvoice_preflight/checks.py so
// the browser page and the CLI report the same rule IDs, messages, and
// cent-rounded arithmetic. This is an observation, not a legal validity claim.

import { headerAdjustmentNetDelta, inspectHeaderAdjustments } from "./adjustment.mjs";
import { inspectPaymentBic } from "./bic.mjs";
import { inspectTaxBreakdown } from "./breakdown.mjs";
import { inspectDocumentType } from "./document.mjs";
import { inspectPartyEndpoint } from "./endpoint.mjs";
import { inspectPaymentIban } from "./iban.mjs";
import { inspectPaymentMeans } from "./means.mjs";
import { inspectInvoicePeriod } from "./period.mjs";
import { inspectCommercialReferences } from "./reference.mjs";
import { inspectPaymentRemittance } from "./remittance.mjs";
import { inspectTaxExemption } from "./tax.mjs";
import { inspectPaymentTerms } from "./terms.mjs";
import { inspectPartyVat } from "./vat.mjs";

function parseNumber(value) {
  if (value === undefined || value === null || value === "") return null;
  const text = typeof value === "string" ? value.trim() : String(value);
  if (text === "" || !Number.isFinite(Number(text))) return null;
  const result = Number(text);
  return Number.isFinite(result) ? result : null;
}

export function roundHalfUpToCents(value) {
  if (!Number.isFinite(value)) return null;
  const sign = value < 0 ? -1 : 1;
  return (sign * Math.round(Math.abs(value) * 100 + Number.EPSILON)) / 100;
}

function money(value) {
  const parsed = parseNumber(value);
  return parsed === null ? null : roundHalfUpToCents(parsed);
}

function isoDate(value) {
  if (typeof value !== "string" || value.length !== 10 || value[4] !== "-" || value[7] !== "-") {
    return null;
  }
  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(5, 7));
  const day = Number(value.slice(8, 10));
  if (![year, month, day].every((part) => Number.isInteger(part))) return null;
  const date = new Date(Date.UTC(year, month - 1, day));
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }
  return date;
}

export function checkInvoice(invoice) {
  const errors = [];
  const fail = (rule, message, fix, path = "") => {
    errors.push({ rule, message, fix, path });
  };

  if (invoice === null || typeof invoice !== "object" || Array.isArray(invoice)) {
    return [{
      rule: "INV-001",
      message: "Invoice must be a JSON object.",
      fix: "Provide the invoice object at the document root.",
      path: "",
    }];
  }

  for (const field of ["invoice_number", "issue_date", "currency", "supplier", "customer", "lines", "totals"]) {
    if (!(field in invoice)) {
      fail("INV-001", `Required field '${field}' is missing.`, `Add a '${field}' field.`, `/${field}`);
    }
  }

  if (typeof invoice.invoice_number !== "string" || !invoice.invoice_number.trim()) {
    fail("INV-002", "Invoice number is empty or not text.", "Provide a non-empty invoice number.", "/invoice_number");
  }

  const issueDate = isoDate(invoice.issue_date);
  if (issueDate === null) {
    fail("INV-003", "Issue date is not an ISO date.", "Use YYYY-MM-DD, for example 2026-08-24.", "/issue_date");
  }

  if ("due_date" in invoice && invoice.due_date !== null && invoice.due_date !== "") {
    const dueDate = isoDate(invoice.due_date);
    if (dueDate === null) {
      fail("INV-020", "Due date is not an ISO date.", "Use YYYY-MM-DD, for example 2026-09-23.", "/due_date");
    }
    if (dueDate !== null && issueDate !== null && dueDate < issueDate) {
      fail("INV-021", "Due date is earlier than the issue date.", "Set due date to the issue date or a later date.", "/due_date");
    }
  }

  if (
    typeof invoice.currency !== "string" ||
    invoice.currency.length !== 3 ||
    invoice.currency === invoice.currency.toLowerCase() ||
    invoice.currency !== invoice.currency.toUpperCase()
  ) {
    fail("INV-004", "Currency is not a three-letter uppercase code.", "Use an ISO-style code such as EUR or GBP.", "/currency");
  }

  for (const partyName of ["supplier", "customer"]) {
    const party = invoice[partyName];
    if (!party || typeof party !== "object" || Array.isArray(party) || typeof party.id !== "string" || !party.id.trim()) {
      fail("INV-005", `${capitalize(partyName)} identifier is missing.`, `Add the ${partyName} identifier from the source system.`, `/${partyName}/id`);
    }
    if (!party || typeof party !== "object" || Array.isArray(party) || typeof party.name !== "string" || !party.name.trim()) {
      fail("INV-006", `${capitalize(partyName)} name is missing.`, `Add the ${partyName} name.`, `/${partyName}/name`);
    }
    if (party && typeof party === "object" && !Array.isArray(party)) {
      for (const finding of inspectPartyVat(party, partyName)) {
        fail(finding.rule, finding.message, finding.fix, finding.path);
      }
      for (const finding of inspectPartyEndpoint(party, partyName)) {
        fail(finding.rule, finding.message, finding.fix, finding.path);
      }
    }
  }
  for (const finding of inspectPaymentIban(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectPaymentMeans(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectPaymentTerms(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectPaymentBic(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectPaymentRemittance(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectDocumentType(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectTaxExemption(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectTaxBreakdown(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectInvoicePeriod(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectCommercialReferences(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }
  for (const finding of inspectHeaderAdjustments(invoice)) {
    fail(finding.rule, finding.message, finding.fix, finding.path);
  }

  let lines = invoice.lines;
  if (!Array.isArray(lines) || lines.length === 0) {
    fail("INV-007", "Invoice has no line items.", "Add at least one line item.", "/lines");
    lines = [];
  }

  let expectedNet = 0;
  let expectedTax = 0;
  lines.forEach((line, index) => {
    const n = index + 1;
    if (!line || typeof line !== "object" || Array.isArray(line)) {
      fail("INV-008", `Line ${n} is not an object.`, "Provide description, quantity, unit_price, and tax_percent.", `/lines/${index}`);
      return;
    }
    if (typeof line.description !== "string" || !line.description.trim()) {
      fail("INV-008", `Line ${n} has no description.`, "Add a human-readable line description.", `/lines/${index}/description`);
    }
    const quantity = parseNumber(line.quantity);
    const price = money(line.unit_price);
    const tax = parseNumber(line.tax_percent);
    if (quantity === null || quantity <= 0) {
      fail("INV-009", `Line ${n} quantity is invalid.`, "Use a positive numeric quantity.", `/lines/${index}/quantity`);
    }
    if (price === null || price < 0) {
      fail("INV-010", `Line ${n} unit price is invalid.`, "Use a non-negative numeric unit price.", `/lines/${index}/unit_price`);
    }
    if (tax === null || tax < 0 || tax > 100) {
      fail(
        "INV-011",
        `Line ${n} tax percentage is invalid.`,
        "Use the tax percentage supplied by your authoritative source; this tool does not choose it.",
        `/lines/${index}/tax_percent`,
      );
    }
    if (quantity !== null && price !== null && quantity > 0 && price >= 0) {
      const lineNet = roundHalfUpToCents(quantity * price);
      expectedNet = roundHalfUpToCents(expectedNet + lineNet);
      if (tax !== null && tax >= 0 && tax <= 100) {
        expectedTax = roundHalfUpToCents(expectedTax + roundHalfUpToCents((lineNet * tax) / 100));
      }
      const supplied = money(line.net);
      if (supplied === null || supplied !== lineNet) {
        fail(
          "INV-012",
          `Line ${n} net is missing or does not match quantity times unit price.`,
          `Set line net to ${formatMoney(lineNet)} or correct the inputs.`,
          `/lines/${index}/net`,
        );
      }
    }
  });
  expectedNet = roundHalfUpToCents(expectedNet + headerAdjustmentNetDelta(invoice));
  if (expectedNet < 0) expectedNet = 0;

  const totals = invoice.totals && typeof invoice.totals === "object" && !Array.isArray(invoice.totals)
    ? invoice.totals
    : {};
  const net = money(totals.net);
  const taxTotal = money(totals.tax);
  const gross = money(totals.gross);

  if (net === null || net < 0) {
    fail("INV-013", "Invoice net total is missing or invalid.", "Provide a non-negative numeric net total.", "/totals/net");
  } else if (net !== expectedNet) {
    if (invoice.adjustments) {
      fail("INV-014", "Invoice net total does not match line items after header allowances and charges.", `Set net total to ${formatMoney(expectedNet)} or correct the line items and adjustments.`, "/totals/net");
    } else {
      fail("INV-014", "Invoice net total does not match its line items.", `Set net total to ${formatMoney(expectedNet)} or correct the line items.`, "/totals/net");
    }
  }
  if (taxTotal === null || taxTotal < 0) {
    fail("INV-015", "Invoice tax total is missing or invalid.", "Provide a non-negative numeric tax total.", "/totals/tax");
  } else if (taxTotal !== expectedTax) {
    fail("INV-018", "Invoice tax total does not match its line tax percentages.", `Set tax total to ${formatMoney(expectedTax)} or correct the line inputs.`, "/totals/tax");
  }
  if (gross === null || gross < 0) {
    fail("INV-016", "Invoice gross total is missing or invalid.", "Provide a non-negative numeric gross total.", "/totals/gross");
  } else if (net !== null && taxTotal !== null && gross !== roundHalfUpToCents(net + taxTotal)) {
    fail("INV-017", "Gross total does not equal net plus tax.", `Set gross total to ${formatMoney(roundHalfUpToCents(net + taxTotal))} or correct the totals.`, "/totals/gross");
  }

  const prepaid = optionalMoney(totals, "prepaid");
  if (prepaid !== undefined) {
    if (prepaid === null || prepaid < 0) {
      fail("INV-028", "Prepaid amount is missing or invalid.", "Provide a non-negative numeric prepaid amount, or omit totals.prepaid.", "/totals/prepaid");
    } else if (gross !== null && gross >= 0 && prepaid > gross) {
      fail("INV-028", "Prepaid amount is greater than the invoice gross.", `Set prepaid to at most ${formatMoney(gross)} or correct the totals.`, "/totals/prepaid");
    }
  }
  const due = optionalMoney(totals, "due");
  if (due !== undefined) {
    if (due === null || due < 0) {
      fail("INV-029", "Amount due is missing or invalid.", "Provide a non-negative numeric amount due, or omit totals.due.", "/totals/due");
    } else if (gross !== null && gross >= 0 && (prepaid === undefined || prepaid === null || prepaid >= 0)) {
      const applied = prepaid !== undefined && prepaid !== null && prepaid >= 0 ? prepaid : 0;
      let expectedDue = roundHalfUpToCents(gross - applied);
      if (expectedDue < 0) expectedDue = 0;
      if (due !== expectedDue) {
        fail("INV-029", "Amount due does not equal gross minus prepaid.", `Set amount due to ${formatMoney(expectedDue)} or correct prepaid and gross.`, "/totals/due");
      }
    }
  }

  return errors;
}

function optionalMoney(totals, key) {
  if (!(key in totals) || totals[key] === null || totals[key] === "") return undefined;
  return money(totals[key]);
}

function capitalize(value) {
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function formatMoney(value) {
  return value.toFixed(2);
}

// Two suppliers may both issue "1001"; the same supplier issuing it twice is
// the duplicate-payment risk. Key on supplier identity + number (supplier id, VAT
// id, or name; invoices with no seller identity share one bucket).
function sellerKey(invoice) {
  const seller = invoice.supplier && typeof invoice.supplier === "object" ? invoice.supplier : {};
  for (const field of ["id", "vat_id", "name"]) {
    if (typeof seller[field] === "string" && seller[field].trim()) {
      return `${field}:${seller[field].trim().toLowerCase().replace(/\s+/g, " ")}`;
    }
  }
  return "";
}

export function flagDuplicateInvoiceNumbers(invoices) {
  const byNumber = new Map();
  for (const { name, invoice } of invoices) {
    if (invoice && typeof invoice === "object" && typeof invoice.invoice_number === "string") {
      const number = invoice.invoice_number.trim();
      if (!number) continue;
      const key = `${sellerKey(invoice)}\u0000${number}`;
      const list = byNumber.get(key) || [];
      list.push(name);
      byNumber.set(key, list);
    }
  }
  const duplicates = new Set();
  for (const names of byNumber.values()) {
    if (names.length > 1) names.forEach((name) => duplicates.add(name));
  }
  return duplicates;
}

cii.mjs.text:
// Maps a UN/CEFACT CrossIndustryInvoice (XRechnung CII / Factur-X XML)
// into the format-neutral checker shape. Mirrors
// src/einvoice_preflight/formats.py parse_cii_invoice + to_checker_invoice.
// Amounts stay the strings written in the file so the checks convert them
// once. DTD and entity declarations are rejected by parseXmlTree.

import { parseXmlTree } from "./ubl.mjs";

const CII_NS = "urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100";

function descendants(node, name) {
  const found = [];
  const walk = (current) => {
    if (current.name === name) found.push(current);
    for (const child of current.children) walk(child);
  };
  walk(node);
  return found;
}

function firstChild(node, name) {
  if (!node) return null;
  return node.children.find((child) => child.name === name) || null;
}

function textOf(node, name) {
  if (!node) return "";
  const match = descendants(node, name)[0];
  return match ? match.text.trim() : "";
}

function nestedText(node, ...names) {
  let current = node;
  for (const name of names) {
    current = firstChild(current, name);
    if (!current) return "";
  }
  return (current.text || "").trim();
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value) return value;
  }
  return "";
}

function isoDate(value) {
  if (!value) return "";
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
  const digits = value.replace(/\D/g, "");
  if (digits.length === 8) {
    return `${digits.slice(0, 4)}-${digits.slice(4, 6)}-${digits.slice(6, 8)}`;
  }
  return value;
}

export function looksLikeCii(source) {
  const text = typeof source === "string" ? source : new TextDecoder().decode(source);
  return text.includes("CrossIndustryInvoice") || text.includes(CII_NS);
}

function ciiVatId(party) {
  if (!party) return "";
  for (const registration of descendants(party, "SpecifiedTaxRegistration")) {
    const identifier = firstChild(registration, "ID");
    if (!identifier) continue;
    const scheme = (identifier.attrs && identifier.attrs.schemeID) ? identifier.attrs.schemeID.trim() : "";
    if (scheme.toUpperCase() === "VA") return identifier.text.trim();
  }
  return "";
}

function partyFrom(tradeParty) {
  const vatId = ciiVatId(tradeParty);
  const identifier = firstNonEmpty(
    nestedText(tradeParty, "ID"),
    nestedText(tradeParty, "GlobalID"),
    nestedText(tradeParty, "SpecifiedLegalOrganization", "ID"),
    nestedText(tradeParty, "URIUniversalCommunication", "URIID"),
    vatId,
  );
  const mapped = {
    id: identifier,
    name: nestedText(tradeParty, "Name"),
  };
  if (vatId) mapped.vat_id = vatId;
  const address = firstChild(tradeParty, "PostalTradeAddress");
  if (address) {
    const street = nestedText(address, "LineOne");
    const city = nestedText(address, "CityName");
    const postal = nestedText(address, "PostcodeCode");
    const country = nestedText(address, "CountryID");
    if (street) mapped.street = street;
    if (city) mapped.city = city;
    if (postal) mapped.postal_code = postal;
    if (country) mapped.country = country;
  }
  const contactNode = firstChild(tradeParty, "DefinedTradeContact");
  if (contactNode) {
    const contact = {};
    const cName = firstNonEmpty(nestedText(contactNode, "PersonName"), nestedText(contactNode, "DepartmentName"));
    const phone = nestedText(contactNode, "TelephoneUniversalCommunication", "CompleteNumber");
    const email = nestedText(contactNode, "EmailURIUniversalCommunication", "URIID");
    if (cName) contact.name = cName;
    if (phone) contact.phone = phone;
    if (email) contact.email = email;
    if (Object.keys(contact).length) mapped.contact = contact;
  }
  const legalId = firstChild(firstChild(tradeParty, "SpecifiedLegalOrganization"), "ID");
  if (legalId && (legalId.text || "").trim()) {
    mapped.legal_id = { id: legalId.text.trim(), scheme: legalId.attrs && legalId.attrs.schemeID ? String(legalId.attrs.schemeID).trim() : "" };
  }
  const uri = firstChild(firstChild(tradeParty, "URIUniversalCommunication"), "URIID");
  if (uri) {
    const id = (uri.text || "").trim();
    const scheme = uri.attrs && uri.attrs.schemeID ? String(uri.attrs.schemeID).trim() : "";
    if (id || scheme) mapped.endpoint = { id, scheme };
  }
  for (const registration of descendants(tradeParty, "SpecifiedTaxRegistration")) {
    const identifier = firstChild(registration, "ID");
    if (identifier && identifier.attrs && String(identifier.attrs.schemeID || "").trim().toUpperCase() === "FC") {
      mapped.tax_number = identifier.text.trim();
      break;
    }
  }
  return mapped;
}

function parseLine(line) {
  const agreement = firstChild(line, "SpecifiedLineTradeAgreement");
  const delivery = firstChild(line, "SpecifiedLineTradeDelivery");
  const settlement = firstChild(line, "SpecifiedLineTradeSettlement");
  const tax = firstChild(settlement, "ApplicableTradeTax");
  const price = firstChild(agreement, "NetPriceProductTradePrice");
  const mapped = {
    description: firstNonEmpty(
      nestedText(line, "SpecifiedTradeProduct", "Name"),
      nestedText(line, "SpecifiedTradeProduct", "Description"),
    ),
    quantity: nestedText(delivery, "BilledQuantity"),
    unit_price: nestedText(price, "ChargeAmount"),
    tax_percent: nestedText(tax, "RateApplicablePercent"),
    net: nestedText(settlement, "SpecifiedTradeSettlementLineMonetarySummation", "LineTotalAmount"),
  };
  const category = nestedText(tax, "CategoryCode");
  if (category) mapped.tax_category = category;
  return mapped;
}

function vatBreakdown(settlement) {
  if (!settlement) return [];
  const rows = [];
  for (const tax of descendants(settlement, "ApplicableTradeTax")) {
    // Header tax lives directly under ApplicableHeaderTradeSettlement.
    // Line tax uses the same local name, so only take siblings of the
    // header summation / payment means — i.e. children of settlement.
    if (!settlement.children.includes(tax)) continue;
    const row = {
      tax_percent: textOf(tax, "RateApplicablePercent"),
      taxable_amount: textOf(tax, "BasisAmount"),
      tax_amount: textOf(tax, "CalculatedAmount"),
      tax_category: textOf(tax, "CategoryCode"),
      exemption_reason: firstNonEmpty(textOf(tax, "ExemptionReason"), textOf(tax, "ExemptionReasonCode")),
    };
    if (row.tax_percent || row.taxable_amount || row.tax_amount || row.tax_category || row.exemption_reason) {
      rows.push(row);
    }
  }
  return rows;
}

function totalsFrom(settlement) {
  const summation = firstChild(settlement, "SpecifiedTradeSettlementHeaderMonetarySummation");
  return {
    net: textOf(summation, "LineTotalAmount"),
    tax: textOf(summation, "TaxTotalAmount"),
    gross: textOf(summation, "GrandTotalAmount"),
    prepaid: textOf(summation, "TotalPrepaidAmount"),
    payable: textOf(summation, "DuePayableAmount"),
  };
}

function paymentFrom(settlement) {
  const means = firstChild(settlement, "SpecifiedTradeSettlementPaymentMeans");
  const account = firstNonEmpty(
    nestedText(means, "PayeePartyCreditorFinancialAccount", "IBANID"),
    nestedText(means, "PayeePartyCreditorFinancialAccount", "ProprietaryID"),
  );
  const payment = {};
  if (account) payment.iban = account;
  const meansCode = textOf(means, "TypeCode");
  if (meansCode) payment.means = meansCode;
  const remittance = textOf(settlement, "PaymentReference");
  if (remittance) payment.remittance = remittance;
  const termsDays = paymentTermsDays(settlement);
  if (termsDays) payment.terms_days = termsDays;
  return Object.keys(payment).length ? payment : null;
}

function paymentTermsDays(settlement) {
  const terms = firstChild(settlement, "SpecifiedTradePaymentTerms");
  if (!terms) return "";
  const period = firstChild(terms, "SpecifiedPeriod") || terms;
  for (const measure of descendants(period, "DurationMeasure")) {
    const unit = ((measure.attrs && measure.attrs.unitCode) || "").trim().toUpperCase();
    const value = measure.text.trim();
    if (value && (unit === "DAY" || unit === "D")) return value;
  }
  return "";
}

export function parseCiiInvoice(source) {
  const tree = parseXmlTree(source);
  const root = descendants(tree, "CrossIndustryInvoice")[0];
  if (!root) throw new Error("CII document root must be CrossIndustryInvoice");

  const header = firstChild(root, "ExchangedDocument");
  const transaction = firstChild(root, "SupplyChainTradeTransaction");
  const agreement = firstChild(transaction, "ApplicableHeaderTradeAgreement");
  const settlement = firstChild(transaction, "ApplicableHeaderTradeSettlement");
  const typeCode = textOf(header, "TypeCode");
  const breakdown = vatBreakdown(settlement);
  const headerReason = breakdown.find((row) => row.exemption_reason)?.exemption_reason || "";

  const lines = descendants(transaction || { name: "", children: [] }, "IncludedSupplyChainTradeLineItem")
    .map((line) => {
      const mapped = parseLine(line);
      if (headerReason && !mapped.tax_reason) mapped.tax_reason = headerReason;
      return mapped;
    });

  const totals = totalsFrom(settlement);
  const invoice = {
    invoice_number: textOf(header, "ID"),
    issue_date: isoDate(nestedText(header, "IssueDateTime", "DateTimeString") || textOf(header, "DateTimeString")),
    currency: textOf(settlement, "InvoiceCurrencyCode"),
    document_type: typeCode === "381" ? "credit_note" : "invoice",
    supplier: partyFrom(firstChild(agreement, "SellerTradeParty")),
    customer: partyFrom(firstChild(agreement, "BuyerTradeParty")),
    lines,
    totals: {
      net: totals.net,
      tax: totals.tax,
      gross: totals.gross,
    },
  };
  const due = isoDate(nestedText(settlement, "SpecifiedTradePaymentTerms", "DueDateDateTime", "DateTimeString")
    || nestedText(settlement, "DueDateDateTime", "DateTimeString"));
  if (due) invoice.due_date = due;
  if (typeCode) invoice.document_code = typeCode;
  const buyerRef = textOf(agreement, "BuyerReference");
  if (buyerRef) invoice.buyer_reference = buyerRef;
  const specification = nestedText(firstChild(root, "ExchangedDocumentContext"), "GuidelineSpecifiedDocumentContextParameter", "ID");
  if (specification) invoice.specification_id = specification;
  const businessProcess = nestedText(firstChild(root, "ExchangedDocumentContext"), "BusinessProcessSpecifiedDocumentContextParameter", "ID");
  if (businessProcess) invoice.profile_id = businessProcess;
  const orderRef = nestedText(agreement, "BuyerOrderReferencedDocument", "IssuerAssignedID");
  if (orderRef) invoice.order_reference = orderRef;
  if (headerReason) invoice.tax_exemption_reason = headerReason;
  if (totals.prepaid !== "") invoice.totals.prepaid = totals.prepaid;
  if (totals.payable !== "") invoice.totals.payable = totals.payable;

  const taxBreakdown = [];
  for (const row of breakdown) {
    const mapped = {};
    if (row.tax_percent !== "") mapped.tax_percent = row.tax_percent;
    if (row.taxable_amount !== "") mapped.taxable = row.taxable_amount;
    if (row.tax_amount !== "") mapped.tax = row.tax_amount;
    if (row.tax_category) mapped.tax_category = row.tax_category;
    if (Object.keys(mapped).length) taxBreakdown.push(mapped);
  }
  if (taxBreakdown.length) invoice.tax_breakdown = taxBreakdown;

  const payment = paymentFrom(settlement);
  if (payment) invoice.payment = payment;
  const notes = [
    ...descendants(header || { name: "", children: [] }, "IncludedNote").map((note) => nestedText(note, "Content")),
    ...descendants(settlement || { name: "", children: [] }, "SpecifiedTradePaymentTerms").map((terms) => nestedText(terms, "Description")),
  ].filter(Boolean);
  if (notes.length) invoice.notes = notes;
  return invoice;
}

document.mjs.text:
// Offline document-type and credit-note reference observations.
// Shape check only — not a Peppol profile determination.

const TYPES = {
  invoice: "invoice",
  "commercial invoice": "invoice",
  "corrected invoice": "invoice",
  "self billed invoice": "invoice",
  "prepayment invoice": "invoice",
  380: "invoice",
  384: "invoice",
  386: "invoice",
  389: "invoice",
  "credit note": "credit_note",
  creditnote: "credit_note",
  credit: "credit_note",
  "self billed credit note": "credit_note",
  381: "credit_note",
  261: "credit_note",
  "debit note": "debit_note",
  debitnote: "debit_note",
  debit: "debit_note",
  383: "debit_note",
};

const REVERSING = new Set(["credit_note", "debit_note"]);

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function normalizeDocumentType(value) {
  if (value === undefined || value === null) return null;
  if (typeof value === "boolean") return "invalid";
  let key;
  if (typeof value === "number" && Number.isInteger(value)) {
    key = String(value);
  } else if (typeof value === "string") {
    key = value.trim().toLowerCase().replace(/[_-]/g, " ").replace(/\s+/g, " ");
    if (!key) return null;
  } else {
    return "invalid";
  }
  if (Object.prototype.hasOwnProperty.call(TYPES, key)) return TYPES[key];
  const compact = key.replace(/ /g, "");
  return Object.prototype.hasOwnProperty.call(TYPES, compact) ? TYPES[compact] : "invalid";
}

function sameReference(left, right) {
  return typeof left === "string"
    && typeof right === "string"
    && left.trim() !== ""
    && left.trim().toLowerCase() === right.trim().toLowerCase();
}

function effectiveType(explicitKind, codeKind) {
  if (explicitKind === "invoice" || explicitKind === "credit_note" || explicitKind === "debit_note") {
    return explicitKind;
  }
  if (codeKind === "invoice" || codeKind === "credit_note" || codeKind === "debit_note") {
    return codeKind;
  }
  return "invoice";
}

export function inspectDocumentType(invoice) {
  if (!invoice || typeof invoice !== "object" || Array.isArray(invoice)) return [];
  const findings = [];
  const explicitKind = normalizeDocumentType(invoice.document_type);
  const codeKind = normalizeDocumentType(invoice.document_code);

  if (invoice.document_type !== undefined && invoice.document_type !== null && invoice.document_type !== "" && explicitKind === "invalid") {
    findings.push(finding(
      "INV-032",
      "Document type is not a known invoice, credit note, or debit note.",
      "Use invoice, credit_note, or debit_note, or omit document_type.",
      "/document_type",
    ));
  }
  if (invoice.document_code !== undefined && invoice.document_code !== null && invoice.document_code !== "" && codeKind === "invalid") {
    findings.push(finding(
      "INV-032",
      "Document type code is not a known invoice, credit note, or debit note code.",
      "Use a UN/CEFACT 1001 code such as 380, 381, or 383, or omit document_code.",
      "/document_code",
    ));
  }

  if (
    (explicitKind === "invoice" || explicitKind === "credit_note" || explicitKind === "debit_note")
    && (codeKind === "invoice" || codeKind === "credit_note" || codeKind === "debit_note")
    && explicitKind !== codeKind
  ) {
    findings.push(finding(
      "INV-034",
      explicitKind === "invoice"
        ? "This document is marked as a commercial invoice but its type code is a credit or debit note."
        : "This document's type and type code do not describe the same kind of document.",
      "Send a CreditNote when the type code is 381, or set document_type to match document_code.",
      "/document_code",
    ));
  }

  const effective = effectiveType(explicitKind, codeKind);
  const needsOriginal = REVERSING.has(effective)
    || (explicitKind === "invoice" && REVERSING.has(codeKind));
  if (needsOriginal) {
    const original = invoice.original_invoice;
    const missing = original === undefined || original === null || original === ""
      || (typeof original === "string" && !original.trim());
    if (missing) {
      findings.push(finding(
        "INV-033",
        "Credit or debit note is missing the original invoice it reverses.",
        "Add original_invoice with the invoice number being credited or debited.",
        "/original_invoice",
      ));
    } else if (typeof original !== "string") {
      findings.push(finding(
        "INV-033",
        "Original invoice reference is empty or not text.",
        "Provide original_invoice as text, or omit document_type if this is a commercial invoice.",
        "/original_invoice",
      ));
    } else if (sameReference(original, invoice.invoice_number)) {
      findings.push(finding(
        "INV-034",
        "This credit or debit note names itself as the invoice it reverses.",
        "Set original_invoice to the invoice being credited or debited, not this document's own number.",
        "/original_invoice",
      ));
    }
  }
  return findings;
}

endpoint.mjs.text:
// Offline buyer/seller electronic-address (EndpointID) observations.
// Shape and typo check only — not a directory lookup. Findings never
// repeat the address.

const KNOWN_SCHEMES = new Set([
  "0002", "0007", "0009", "0037", "0060", "0088", "0096", "0130", "0151",
  "0183", "0184", "0190", "0191", "0192", "0193", "0195", "0196", "0198",
  "0201", "0204", "0208", "0209", "0210", "0211", "0212", "0213", "0216",
  "0221", "0230", "0235", "0240",
  "9910", "9913", "9914", "9915", "9918", "9919",
  "9920", "9922", "9923", "9924", "9925", "9926", "9927", "9928", "9929",
  "9930", "9931", "9932", "9933", "9934", "9935", "9936", "9937", "9938",
  "9939", "9940", "9941", "9942", "9943", "9944", "9945", "9946", "9947",
  "9948", "9950", "9951", "9952", "9953", "9955", "9956", "9957", "9958",
  "EM",
]);

function finding(rule, message, fix, path) {
  return { rule, message, fix, path };
}

export function normalizeScheme(value) {
  if (typeof value !== "string") return null;
  const compact = value.trim().toUpperCase();
  return compact || null;
}

export function normalizeEndpointId(value) {
  if (typeof value !== "string") return null;
  const stripped = value.trim();
  return stripped || null;
}

export function looksLikeKnownScheme(value) {
  const scheme = normalizeScheme(value);
  return scheme !== null && KNOWN_SCHEMES.has(scheme);
}

function digits(identifier, length) {
  const compact = identifier.replace(/\D/g, "");
  return compact.length === length;
}

function glnOk(identifier) {
  const compact = identifier.replace(/\D/g, "");
  if (compact.length !== 13) return false;
  let total = 0;
  for (let index = 0; index < 12; index += 1) {
    total += Number(compact[index]) * (index % 2 === 0 ? 1 : 3);
  }
  const check = (10 - (total % 10)) % 10;
  return check === Number(compact[12]);
}

function emailOk(identifier) {
  if (identifier !== identifier.trim() || identifier.includes(" ") || identifier.split("@").length !== 2) {
    return false;
  }
  const [local, domain] = identifier.split("@");
  return Boolean(local) && domain.includes(".") && !domain.startsWith(".") && !domain.endsWith(".");
}

function schemeIdOk(scheme, identifier) {
  if (scheme === "0088") return glnOk(identifier);
  if (scheme === "EM") return emailOk(identifier);
  if (scheme === "0007") return digits(identifier, 10);
  if (scheme === "0184") return digits(identifier, 8);
  if (scheme === "0190") return digits(identifier, 20);
  if (scheme === "0192") return digits(identifier, 9);
  if (scheme === "0208") return digits(identifier, 10);
  if (scheme === "0212") {
    const compact = identifier.replace(/[^A-Za-z0-9]/g, "");
    return (compact.length === 8 || compact.length === 9) && /^\d+$/.test(compact.slice(0, -1));
  }
  return identifier.replace(/[^A-Za-z0-9@.\-_:\/+]/g, "") !== "";
}

export function inspectPartyEndpoint(party, partyName) {
  if (!party || typeof party !== "object" || !("endpoint" in party)) return [];
  const endpoint = party.endpoint;
  if (endpoint === null || endpoint === "") return [];
  const path = `/${partyName}/endpoint`;
  const label = partyName.charAt(0).toUpperCase() + partyName.slice(1);
  if (!endpoint || typeof endpoint !== "object" || Array.isArray(endpoint)) {
    return [finding(
      "INV-039",
      `${label} electronic address is not an object with scheme and id.`,
      `Use ${partyName}.endpoint.scheme (EAS code) and ${partyName}.endpoint.id, or omit endpoint.`,
      path,
    )];
  }

  const findings = [];
  const scheme = normalizeScheme(endpoint.scheme);
  const identifier = normalizeEndpointId(endpoint.id);
  if (scheme === null || !KNOWN_SCHEMES.has(scheme)) {
    findings.push(finding(
      "INV-039",
      `${label} electronic-address scheme is missing or not a published EAS code.`,
      "Use a Peppol EAS scheme such as 0088 (GLN), 0192, 0208, or EM, or omit endpoint.",
      `${path}/scheme`,
    ));
  }
  if (identifier === null) {
    findings.push(finding(
      "INV-040",
      `${label} electronic address is empty or not text.`,
      `Provide ${partyName}.endpoint.id as text, or omit endpoint.`,
      `${path}/id`,
    ));
  }
  if (scheme !== null && KNOWN_SCHEMES.has(scheme) && identifier !== null && !schemeIdOk(scheme, identifier)) {
    findings.push(finding(
      "INV-041",
      `${label} electronic address does not match the published ${scheme} shape.`,
      `Correct the ${scheme} identifier. This is a format typo check, not a directory lookup.`,
      `${path}/id`,
    ));
  }
  return findings;
}

export function inspectPartyEndpoints(invoice) {
  if (!invoice || typeof invoice !== "object" || Array.isArray(invoice)) return [];
  const findings = [];
  for (const partyName of ["supplier", "customer"]) {
    const party = invoice[partyName];
    if (party && typeof party === "object" && !Array.isArray(party)) {
      findings.push(...inspectPartyEndpoint(party, partyName));
    }
  }
  return findings;
}

